import{_ as e,o as t,c as i,a3 as s}from"./chunks/framework.D3oaa6bG.js";const u=JSON.parse('{"title":"Product","description":"","frontmatter":{},"headers":[],"relativePath":"guide/components/product.md","filePath":"guide/components/product.md","lastUpdated":null}'),n={name:"guide/components/product.md"};function o(r,a,d,l,p,h){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="product" tabindex="-1">Product <a class="header-anchor" href="#product" aria-label="Permalink to &quot;Product&quot;">​</a></h1><p>The <code>Product</code> component displays a single <a href="/wn-mall-plugin/guide/usage/products.html"><code>Product</code> or <code>Variant</code></a>.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="product-mixed" tabindex="-1"><code>product</code> (mixed) <a class="header-anchor" href="#product-mixed" aria-label="Permalink to &quot;`product` (mixed)&quot;">​</a></h3><p>Display a specific <code>Product</code>. Possible values are:</p><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>:slug</code></td><td>Use the page&#39;s <code>:slug</code> URL parameter to find the Product to display</td></tr><tr><td><code>8</code></td><td>Display the Product with ID <code>8</code> (use any integer)</td></tr></tbody></table><h3 id="variant-mixed" tabindex="-1"><code>variant</code> (mixed) <a class="header-anchor" href="#variant-mixed" aria-label="Permalink to &quot;`variant` (mixed)&quot;">​</a></h3><p>Display a specific <code>Variant</code>. Possible values are:</p><table tabindex="0"><thead><tr><th>Value</th><th>Description</th></tr></thead><tbody><tr><td><code>:slug</code></td><td>Use the page&#39;s <code>:slug</code> URL parameter to find the Variant to display</td></tr><tr><td><code>8</code></td><td>Display the Variant with ID <code>8</code> (use any integer)</td></tr></tbody></table><h3 id="redirectonpropertychange-boolean" tabindex="-1"><code>redirectOnPropertyChange</code> (boolean) <a class="header-anchor" href="#redirectonpropertychange-boolean" aria-label="Permalink to &quot;`redirectOnPropertyChange` (boolean)&quot;">​</a></h3><p>Redirect the user to the new Variant/Product detail page if a property was changed.</p><p>Default behaviour is to only reload the &quot;add to cart&quot; partial where new pricing information and stock values are displayed. The title, description and product images remain unchanged. Set this property to true if you need the whole page to update.</p><h3 id="filteroutofstock-boolean" tabindex="-1"><code>filterOutOfStock</code> (boolean) <a class="header-anchor" href="#filteroutofstock-boolean" aria-label="Permalink to &quot;`filterOutOfStock` (boolean)&quot;">​</a></h3><p>By default, the component will display all available variants.</p><p>Set this property to true to only display variants that are in stock.</p><h3 id="currentvariantreviewsonly-boolean" tabindex="-1"><code>currentVariantReviewsOnly</code> (boolean) <a class="header-anchor" href="#currentvariantreviewsonly-boolean" aria-label="Permalink to &quot;`currentVariantReviewsOnly` (boolean)&quot;">​</a></h3><p>If Reviews are enabled, display only Reviews for the currently viewed Variant.</p><p>By default Reviews from all Variants of the same Product are shown.</p><h2 id="example-implementations" tabindex="-1">Example implementations <a class="header-anchor" href="#example-implementations" aria-label="Permalink to &quot;Example implementations&quot;">​</a></h2><h3 id="display-the-variant-defined-in-the-url" tabindex="-1">Display the Variant defined in the URL <a class="header-anchor" href="#display-the-variant-defined-in-the-url" aria-label="Permalink to &quot;Display the Variant defined in the URL&quot;">​</a></h3><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[product]</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">product</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;:slug&quot;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">variant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;:slug&quot;</span></span></code></pre></div><h3 id="display-variant-id-2-of-product-id-1" tabindex="-1">Display Variant ID 2 of Product ID 1 <a class="header-anchor" href="#display-variant-id-2-of-product-id-1" aria-label="Permalink to &quot;Display Variant ID 2 of Product ID 1&quot;">​</a></h3><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[product]</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">product</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1&quot;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">variant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2&quot;</span></span></code></pre></div><h3 id="always-update-the-whole-page-if-a-product-property-has-changed" tabindex="-1">Always update the whole page if a product property has changed <a class="header-anchor" href="#always-update-the-whole-page-if-a-product-property-has-changed" aria-label="Permalink to &quot;Always update the whole page if a product property has changed&quot;">​</a></h3><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[product]</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">product</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;:slug&quot;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">variant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;:slug&quot;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">redirectOnPropertyChange</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 1</span></span></code></pre></div><h3 id="example-of-usage" tabindex="-1">Example of Usage <a class="header-anchor" href="#example-of-usage" aria-label="Permalink to &quot;Example of Usage&quot;">​</a></h3><p>When considering &#39;product&#39; as our component, we can access the reviews in the following manner:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% for review in product.product.reviews  %}</span></span></code></pre></div>',28)])])}const k=e(n,[["render",o]]);export{u as __pageData,k as default};
